import{_ as h,C as c,o as e,c as u,j as n,a,E as o}from"./chunks/framework.Bf1r8NYr.js";const y=JSON.parse('{"title":"Quiz — Bài 6","description":"","frontmatter":{"quizKey":"module-6-fair-ai","questions":[{"id":"6.1.","text":"FAIR có nghĩa là dữ liệu phải công khai không?","options":[{"key":"A","text":"Có, vì dữ liệu đạt FAIR khi người dùng tải được toàn bộ tệp theo chính sách truy cập."},{"key":"B","text":"Không, dữ liệu có thể FAIR với metadata mở và quyền truy cập dữ liệu được kiểm soát."},{"key":"C","text":"FAIR phù hợp với dữ liệu không chứa thông tin sức khỏe hoặc thông tin nhạy cảm."},{"key":"D","text":"Có, dữ liệu đạt FAIR khi đã được đăng trên một kho dữ liệu công cộng."}],"answer":"B","explain":"FAIR yêu cầu khả năng tìm, truy cập theo điều kiện, liên thông và tái sử dụng; không buộc mở hết."},{"id":"6.2.","text":"Bốn nguyên tắc FAIR nhấn mạnh những khả năng nào của dữ liệu?","options":[{"key":"A","text":"Dữ liệu phải được lưu cục bộ, mã hóa, sao lưu và giữ nguyên bản."},{"key":"B","text":"Dữ liệu phải được công khai, tải xuống, phân tích và dùng lại không hạn chế."},{"key":"C","text":"Dữ liệu phải tìm được, truy cập được, liên thông được và tái sử dụng được."},{"key":"D","text":"Dữ liệu phải có kích thước lớn, nhiều biến, ít ô trống và một định dạng chung."}],"answer":"C","explain":"FAIR mô tả cách dữ liệu được tìm thấy, truy cập, kết hợp và dùng lại có trách nhiệm."},{"id":"6.3.","text":"Vì sao xóa file thông thường chưa đủ khi hủy dữ liệu nghiên cứu?","options":[{"key":"A","text":"Vì các tệp nghiên cứu phải được giữ lại theo chính sách để phục vụ tái sử dụng."},{"key":"B","text":"Vì xóa file làm hỏng thiết bị lưu trữ và các tệp khác trên thiết bị đó."},{"key":"C","text":"Vì việc hủy dữ liệu liên quan đến thủ tục giấy tờ và việc ghi chép của nhóm nghiên cứu về thiết bị lưu trữ."},{"key":"D","text":"Vì dữ liệu có thể còn khôi phục được; cần quy trình hủy phù hợp với thiết bị và chính sách."}],"answer":"D","explain":"Xóa thông thường chưa chứng minh dữ liệu không thể khôi phục, nên cần quy trình hủy an toàn phù hợp."},{"id":"6.4.","text":"Tình huống: Một nhóm muốn chia sẻ dữ liệu bệnh nhân nhưng không muốn công khai. Cách làm nào phù hợp với FAIR?","options":[{"key":"A","text":"Chia sẻ metadata để dữ liệu được tìm thấy, rồi cấp quyền truy cập theo điều kiện."},{"key":"B","text":"Không mô tả dữ liệu để tránh người khác biết dữ liệu đang tồn tại."},{"key":"C","text":"Công khai toàn bộ dữ liệu vì FAIR yêu cầu tài nguyên phải được mở."},{"key":"D","text":"Gửi tệp qua kênh cá nhân mà không cần thỏa thuận hoặc kiểm soát truy cập."}],"answer":"A","explain":"Dữ liệu nhạy cảm vẫn có thể FAIR khi được mô tả rõ và truy cập theo quy trình được kiểm soát."}]},"headers":[],"relativePath":"course/module-6-fair-ai/quiz.md","filePath":"course/module-6-fair-ai/quiz.md"}'),l={name:"course/module-6-fair-ai/quiz.md"};function r(g,t,p,s,d,k){const i=c("Quiz",!0);return e(),u("div",null,[t[0]||(t[0]=n("h1",{id:"quiz-—-bai-6",tabindex:"-1"},[a("Quiz — Bài 6 "),n("a",{class:"header-anchor",href:"#quiz-—-bai-6","aria-label":'Permalink to "Quiz — Bài 6"'},"​")],-1)),o(i)])}const x=h(l,[["render",r]]);export{y as __pageData,x as default};
